CREATE TABLE dead_weight_dismissals (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deck_id INTEGER NOT NULL REFERENCES decks(id) ON DELETE CASCADE, card_name TEXT NOT NULL, user_id UUID NOT NULL, dismissed_at TIMESTAMPTZ DEFAULT now(), UNIQUE(deck_id, card_name));
CREATE INDEX idx_dw_dismissals_deck ON dead_weight_dismissals(deck_id);
CREATE INDEX idx_dw_dismissals_user_id ON dead_weight_dismissals(user_id);
CREATE TABLE precon_mod_state (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deck_id INTEGER NOT NULL REFERENCES decks(id) ON DELETE CASCADE, swaps_used INTEGER DEFAULT 1, sol_ring_removed BOOLEAN DEFAULT FALSE, rarity_mythic_used INTEGER DEFAULT 0, rarity_rare_used INTEGER DEFAULT 0, rarity_uncommon_used INTEGER DEFAULT 0, rarity_common_used INTEGER DEFAULT 0, budget_spent NUMERIC DEFAULT 0.0, user_id UUID NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(deck_id));
CREATE INDEX idx_precon_mod_state_deck ON precon_mod_state(deck_id);
CREATE INDEX idx_precon_mod_state_user_id ON precon_mod_state(user_id);
CREATE TABLE upgrade_change_log (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deck_id INTEGER NOT NULL REFERENCES decks(id) ON DELETE CASCADE, cut_card TEXT NOT NULL, add_card TEXT NOT NULL, reason TEXT DEFAULT '', skipped BOOLEAN NOT NULL DEFAULT FALSE, user_id UUID NOT NULL, date DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE INDEX idx_upgrade_change_log_deck ON upgrade_change_log(deck_id);
CREATE INDEX idx_upgrade_change_log_user_id ON upgrade_change_log(user_id);
CREATE TABLE sync_runs (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, trigger TEXT NOT NULL CHECK(trigger IN ('csv_import', 'manual', 'card_movement', 'scheduled')), decks_processed INTEGER DEFAULT 0, decks_succeeded INTEGER DEFAULT 0, decks_failed INTEGER DEFAULT 0, details TEXT, user_id UUID NOT NULL);
CREATE INDEX idx_sync_runs_user_id ON sync_runs(user_id);
CREATE TABLE debrief_sessions (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deck_id INTEGER NOT NULL REFERENCES decks(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'investigating' CHECK(status IN ('investigating', 'analysing', 'recommending', 'complete', 'abandoned')), brief_json TEXT, recommendations_json TEXT, current_rec_index INTEGER DEFAULT 0, conversation_json TEXT, user_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE INDEX idx_debrief_sessions_deck ON debrief_sessions(deck_id, status);
CREATE INDEX idx_debrief_sessions_user_id ON debrief_sessions(user_id);
CREATE TABLE debrief_actions (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES debrief_sessions(id) ON DELETE CASCADE, action_type TEXT NOT NULL CHECK(action_type IN ('applied', 'skipped', 'disagreed', 'error')), cut_card TEXT NOT NULL, add_card TEXT NOT NULL, reason TEXT NOT NULL, notion_logged BOOLEAN NOT NULL DEFAULT FALSE, user_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_debrief_actions_session ON debrief_actions(session_id);
CREATE INDEX idx_debrief_actions_user_id ON debrief_actions(user_id);
CREATE TABLE brew_sessions (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deck_id INTEGER REFERENCES decks(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'selecting' CHECK(status IN ('selecting', 'investigating', 'confirming', 'generating', 'refining', 'saving', 'complete', 'abandoned', 'exploring', 'building')), path_type TEXT CHECK(path_type IN ('commander', 'concept')), commander_name TEXT, colour_identity TEXT, concept_description TEXT, brief_json TEXT, skeleton_json TEXT, refinement_history_json TEXT DEFAULT '[]', conversation_json TEXT DEFAULT '[]', decision_log_json TEXT DEFAULT '{"strategy":[],"parameters":[],"constraints":[]}', assessment_cache_json TEXT DEFAULT '{}', model_id TEXT DEFAULT NULL, user_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_brew_sessions_status ON brew_sessions(status);
CREATE INDEX idx_brew_sessions_updated ON brew_sessions(updated_at DESC);
CREATE INDEX idx_brew_sessions_user_id ON brew_sessions(user_id);;
